```python
def convert_table_to_text(table):
    paragraph = ""
    for row in table:
        sentence = ""
        for i, value in enumerate(row):
            if i == 0:
                sentence += f"The {row[i]} "
            elif i == len(row) - 1:
                sentence += f"{value}."
            else:
                sentence += f"{row[i]} {value}, "
        paragraph += sentence + " "
    return paragraph.strip()
```
